#!/usr/bin/env bash
# Standalone SFT for belief-state JSONL → Qwen2.5-3B-Instruct (no verl).
# Dataset format: goal + previous_belief_state + current_obs → belief_state
# (generated by meow_tea_experiments/data_generation/generate_belief_state_dataset.py)
# Requires: torch, transformers, trl, datasets, accelerate  (+ peft if using LoRA)
#
# Multi-GPU: set NUM_GPUS (default: count visible GPUs, else 1). Uses accelerate launch when NUM_GPUS>1.
# Single-GPU on a multi-GPU box: CUDA_VISIBLE_DEVICES=0 NUM_GPUS=1 ./recipes/...
# Resume: append --resume (latest checkpoint in OUTPUT_DIR) or --resume_from_checkpoint PATH

set -euo pipefail
cd "$(dirname "$0")/.."

TRAIN_JSONL="${TRAIN_JSONL:-/home/user/textworld-RL/local/alfworld_belief_dataset/train_belief.jsonl}"
OUTPUT_DIR="${OUTPUT_DIR:-local/checkpoints/alfworld-belief-sft-qwen3b}"
MODEL="${MODEL:-Qwen/Qwen3-4B-Instruct-2507}"
# All visible GPUs by default (unset CUDA_VISIBLE_DEVICES). Subset: CUDA_VISIBLE_DEVICES=0,1 ...
# Count via torch (respects CUDA_VISIBLE_DEVICES); fall back to nvidia-smi line count.
if [[ -z "${NUM_GPUS:-}" ]]; then
  NUM_GPUS=$(python3 -c 'import torch; print(torch.cuda.device_count())' 2>/dev/null || true)
  if [[ -z "${NUM_GPUS:-}" ]] || [[ "${NUM_GPUS}" -lt 1 ]]; then
    if command -v nvidia-smi >/dev/null 2>&1; then
      NUM_GPUS=$(nvidia-smi -L 2>/dev/null | wc -l | tr -d ' ')
    fi
  fi
  if [[ -z "${NUM_GPUS:-}" ]] || [[ "${NUM_GPUS}" -lt 1 ]]; then
    NUM_GPUS=1
  fi
fi

TRAIN_ARGS=(
  meow_tea_experiments/scripts/finetune_belief_state_sft_alfworld.py
  --train_jsonl "$TRAIN_JSONL"
  --output_dir "$OUTPUT_DIR"
  --model_name_or_path "$MODEL"
  --max_length 4096
  --adaptive_max_length
  --num_train_epochs 5
  --per_device_train_batch_size 4
  --gradient_accumulation_steps 8
  --learning_rate 2e-5
  --bf16
  --lora_r 64 \
  --lora_alpha 128 \
  --save_steps 100
  --logging_steps 5
  --skip_leaked
  "$@"
)

if [[ "${NUM_GPUS}" -gt 1 ]]; then
  accelerate launch --num_processes="${NUM_GPUS}" --multi_gpu "${TRAIN_ARGS[@]}"
else
  python3 "${TRAIN_ARGS[@]}"
fi

